const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Point([43.67, -23.35]).buffer(5000); // Toliara, Madagascar, 5km buffer
  const baselineStart = '2000-09-01';
  const baselineEnd = '2015-09-30';
  const recentStart = '2021-09-01';
  const recentEnd = '2022-09-30';

  // 2. Data Acquisition & Processing Functions
  // Function to mask clouds, shadows, snow, and water using the QA_PIXEL band for Landsat C2 L2
  function maskL8sr(image) {
    const qa = image.select('QA_PIXEL');
    const dilatedCloud = (1 << 1);
    const cirrus = (1 << 2);
    const cloud = (1 << 3);
    const cloudShadow = (1 << 4);
    const mask = qa.bitwiseAnd(dilatedCloud).eq(0)
      .and(qa.bitwiseAnd(cirrus).eq(0))
      .and(qa.bitwiseAnd(cloud).eq(0))
      .and(qa.bitwiseAnd(cloudShadow).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    return image.addBands(image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI'));
  }

  const getLandsatCollection = function(startDate, endDate, geometry) {
    const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .map(maskL8sr)
      .map(addNDVI);
    const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .map(maskL8sr)
      .map(addNDVI);

    // For older Landsat, band names are different for Surface Reflectance
    const addNDVILegacy = image => image.addBands(image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI'));

    const l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterDate(startDate, endDate)
        .filterBounds(geometry)
        .map(maskL8sr) // Same QA mask function works
        .map(addNDVILegacy);

    const l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterDate(startDate, endDate)
        .filterBounds(geometry)
        .map(maskL8sr)
        .map(addNDVILegacy);

    // Merge collections. We select the NDVI band which now exists on all images.
    return ee.ImageCollection(l5.merge(l7).merge(l8).merge(l9)).select('NDVI');
  };

  // 3. Data Analysis
  const baselineCol = getLandsatCollection(baselineStart, baselineEnd, region);
  const recentCol = getLandsatCollection(recentStart, recentEnd, region);

  const baselineSize = baselineCol.size().getInfo();
  const recentSize = recentCol.size().getInfo();

  if (baselineSize === 0 || recentSize === 0) {
    console.log(`Baseline (2000-2015) image count: ${baselineSize}`);
    console.log(`Recent (2021-2022) image count: ${recentSize}`);
    console.log("Empty Collection: No images found for one or both periods.");
    console.log("A");
    return;
  }

  const baselineNDVI = baselineCol.mean();
  const recentNDVI = recentCol.mean();

  const scale = 1000;

  const baselineStats = baselineNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({ reducer2: ee.Reducer.count(), sharedInputs: true }),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const recentStats = recentNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({ reducer2: ee.Reducer.count(), sharedInputs: true }),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const baselineMean = baselineStats.NDVI_mean;
  const baselineCount = baselineStats.NDVI_count;
  const recentMean = recentStats.NDVI_mean;
  const recentCount = recentStats.NDVI_count;

  console.log(`Baseline period (2000-2015): Found ${baselineSize} images.`);
  console.log(`Recent period (2021-2022): Found ${recentSize} images.`);

  if (baselineCount === 0 || recentCount === 0) {
      console.log(`Valid pixel count (Baseline): ${baselineCount}`);
      console.log(`Valid pixel count (Recent): ${recentCount}`);
      console.log("No Valid Pixels: Images exist, but no valid pixels after cloud masking.");
      console.log("C2");
      return;
  }

  if (baselineMean === null || recentMean === null || isNaN(baselineMean) || isNaN(recentMean)) {
      console.log(`Baseline NDVI: ${baselineMean}`);
      console.log(`Recent NDVI: ${recentMean}`);
      console.log("Calculation Failure: Result is null or NaN.");
      console.log("C3");
      return;
  }

  // 4. Validation & Final Answer
  console.log(`Avg. NDVI 2000-2015: ${baselineMean.toFixed(4)} (Pixels: ${baselineCount})`);
  console.log(`Avg. NDVI 2021-2022: ${recentMean.toFixed(4)} (Pixels: ${recentCount})`);

  if (recentMean < baselineMean) {
      console.log("Conclusion: NDVI decreased in the recent period.");
      console.log("A");
  } else {
      console.log("Conclusion: NDVI did not decrease in the recent period.");
      console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log("D");
});
